podman images --format '{{.Repository}}:{{.Tag}} {{.ID}} {{.CreatedAt}}' 2>/dev/null | grep -i "local-llm\|llama" | head; echo ----; cd /home/research/phase0/results/serve && python3 - <<'EOF'
import csv, os, json, time
G=1024**3
for n in ['120b-c32k-np1-dio-cold','L2-120b-greedy','N-120b-greedy','20b-c128k-np4-cram-default','20b-c128k-np4-cram-0']:
    rows=[(float(r['t']),int(r['MemAvailable'])/G,int(r['MemFree'])/G) for r in csv.DictReader(open(n+'-mem.csv'))]
    end=os.stat(n+'-mem.csv').st_mtime; t0=end-rows[-1][0]
    # upward steps >1 GiB within 1 s (excluding the final exit release)
    ups=[]
    for i in range(len(rows)):
        for k in range(i+1,len(rows)):
            if rows[k][0]-rows[i][0]>1.0: break
            if rows[k][1]-rows[i][1]>1.0:
                ups.append((rows[i][0],rows[k][0],rows[k][1]-rows[i][1])); break
    # merge
    merged=[]
    for a,b,d in ups:
        if merged and a<=merged[-1][1]+0.2: merged[-1]=(merged[-1][0],b,max(merged[-1][2],d))
        else: merged.append((a,b,d))
    print(n, 'start', time.strftime('%H:%M:%S',time.localtime(t0)), 'ups:', '; '.join(f"t={a:.1f}-{b:.1f}s ({time.strftime('%H:%M:%S',time.localtime(t0+a))}) +{d:.1f}" for a,b,d in merged))
EOF

